    */
    @Test @Timeout(60)
    fun test_192_postOnLoginShowsFaults_109_200_202()  {
        
        val cookies_userA : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=useraa&password=userAA")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault109. HTTP Violation: no-401-if-no-authenticate.
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/JWT/refresh/login'.
        // Fault202. Schema Violation: no-401-if-no-auth.
        given().accept("*/*")
                .cookies(cookies_userA)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/JWT/refresh/login")
                .then()
                .statusCode(401)
                .assertThat()
                .header("www-authenticate", isEmptyOrNullString())
                .body(isEmptyOrNullString())
    }
    
    
